24: /**
25:  * Hashes a session token for secure database storage.
26:  */
27: function hashToken(token: string): string {
28:   const secret = process.env.SESSION_SECRET || 'nagrikone_session_secret_2026';
29:   return crypto.createHmac('sha256', secret).update(token).digest('hex');
