61:  */
62: export async function getSessionFromToken(token: string): Promise<AuthSession | null> {
63:   if (!token || typeof token !== 'string') return null;
64:   const tokenHash = hashToken(token);
65:   const now = new Date();
66: 
67:   try {
68:     if (db?.session?.findUnique) {
69:       const session = await db.session.findUnique({
70:         where: { tokenHash },
71:         include: { user: true }
72:       });
73: 
74:       if (!session || session.expiresAt < now || !session.user || !session.user.isActive) {
75:         return null;
76:       }
77: 
78:       return {
79:         userId: session.user.id,
80:         name: session.user.name || 'Citizen',
81:         email: session.user.email || undefined,
82:         phone: session.user.phone || undefined,
83:         role: session.user.role as any,
84:         expiresAt: session.expiresAt.toISOString()
85:       };
86:     }
87:   } catch (err) {
88:     console.warn('[NagrikOne Session] Verification error:', err);
89:   }
90: 
91:   return null;
92: }
