323:       if (voiceEnabled) {
324:         speakText(spokenSummary);
325:       } else {
326:         setTimeout(() => setNovaState('IDLE'), 1800);
327:       }
328:     } catch (err: any) {
329:       setErrorMessage(err.message || 'Error analyzing issue with NOVA.');
330:       setNovaState('IDLE');
331:     } finally {
332:       setAnalyzing(false);
333:     }
334:   };
335: 
336:   const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
337:     const files = e.target.files;
338:     if (!files || files.length === 0) return;
339: 
340:     if (!user) {
341:       setAuthPromptMessage('Before we start, please log in so I can securely save your problem, documents and case status.');
342:       setAuthModalOpen(true);
343:       return;
344:     }
345: 
346:     const file = files[0];
347:     const formData = new FormData();
348:     formData.append('file', file);
349: 
350:     try {
351:       const res = await fetch('/api/evidence', {
352:         method: 'POST',
353:         body: formData
354:       });
355: 
356:       const data = await res.json();
357:       if (!res.ok || !data.success) {
358:         throw new Error(data.error || 'Upload verification failed.');
359:       }
360: 
361:       setEvidenceFiles((prev) => [...prev, data.file]);
362:     } catch (err: any) {
363:       setErrorMessage(err.message || 'Could not upload evidence file.');
364:     }
365:   };
366: 
367:   const handleCreatePersistentCase = async () => {
