383:       const isUnknown = classification.isUnknown || classification.domain === 'UNKNOWN' || classification.domain === 'Unclassified / General Citizen Dispute';
384: 
385:       const problemText = (analysisResult.rawText || inputProblem || 'Citizen issue').trim();
386:       const res = await fetch('/api/cases', {
387:         method: 'POST',
388:         headers: { 'Content-Type': 'application/json' },
389:         body: JSON.stringify({
390:           problemTypeId: isUnknown ? undefined : (classification.problemCode || classification.problemId || analysisResult.problem?.id),
391:           title: isUnknown 
392:             ? `Dispute: ${problemText.slice(0, 50)}...`
393:             : `${classification.domain || 'Citizen'} Issue`,
394:           description: problemText,
395:           location: customLocation || 'Unspecified Jurisdiction',
396:           customAnswers: dynamicAnswers,
397:           evidenceFiles: evidenceFiles,
398:           routeRecommendation: route
399:         })
400:       });
401: 
402:       const data = await res.json();
403: 
404:       if (!res.ok || !data.success) {
