430:           setUser(null);
431:         }}
432:       />
433: 
434:       <AuthModal
435:         isOpen={authModalOpen}
436:         onClose={() => setAuthModalOpen(false)}
437:         customPrompt={authPromptMessage}
438:         onLoginSuccess={(u) => {
439:           setUser(u);
440:           setAuthPromptMessage(undefined);
441:         }}
442:       />
443: 
444:       <div className="container-box pt-8 sm:pt-12 max-w-5xl">
445:         
446:         {/* ============================================================ */}
447:         {/* CENTRAL NOVA INTELLIGENCE EXPERIENCE                          */}
448:         {/* ============================================================ */}
449:         <div className="flex flex-col items-center justify-center text-center space-y-4 mb-6">
450:           <div className="inline-flex items-center gap-2 px-3.5 py-1 rounded-full bg-cyan-950/60 border border-cyan-500/30 text-cyan-300 text-xs font-mono">
451:             <Sparkles className="w-3.5 h-3.5" />
452:             <span>NOVA CITIZEN INTELLIGENCE</span>
453:           </div>
454: 
455:           <h1 className="text-3xl sm:text-4xl lg:text-5xl font-black text-slate-50 tracking-tight">
456:             Tell NOVA what you're facing.
457:           </h1>
458: 
459:           {/* Dominant Living 3D Core */}
