477:                 isListening
478:                   ? 'bg-rose-600 text-white shadow-[0_0_20px_rgba(225,29,72,0.5)] animate-pulse'
479:                   : 'bg-slate-900 border border-slate-700 hover:border-cyan-400 text-slate-200'
480:               }`}
481:             >
