501:               {voiceEnabled ? <Volume2 className="w-4 h-4 text-cyan-400" /> : <VolumeX className="w-4 h-4" />}
502:             </button>
503:           </div>
504:         </div>
505: 
506:         {/* ============================================================ */}
507:         {/* CONVERSATION TRANSCRIPT & INPUT AREA                          */}
508:         {/* ============================================================ */}
509:         <div className="rounded-3xl p-5 sm:p-7 bg-gradient-to-b from-[#081322] to-[#040914] border border-slate-800/80 shadow-2xl space-y-6 mb-8">
