534: 
535:                   <div className="whitespace-pre-wrap leading-relaxed space-y-2 text-xs sm:text-sm text-slate-200 font-sans">
536:                     {turn.text}
537:                   </div>
538: 
539:                   {turn.noticeDraft && (
540:                     <div className="mt-3.5 pt-3 border-t border-slate-800/80 flex flex-wrap items-center justify-between gap-2 bg-slate-950/70 p-3 rounded-xl border border-slate-800">
